// Calculate 7-day time window for GitHub API queries
const config = $input.first().json;
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));

return [{
  json: {
    ...config,
    now_iso: now.toISOString(),
    seven_days_ago_iso: sevenDaysAgo.toISOString(),
    start_date: sevenDaysAgo.toISOString().split('T')[0],
    end_date: now.toISOString().split('T')[0],
    period_display: `${sevenDaysAgo.toISOString().split('T')[0]} to ${now.toISOString().split('T')[0]}`
  }
}];

// Extract, normalize, and build prompt for Claude Sonnet 4
const config = $('Calculate 7-Day Window').first().json;
const sevenDaysAgo = new Date(config.seven_days_ago_iso);

// 1. Process Commits
let commitsRaw = $('Fetch GitHub Commits').all();
let commitsList = [];
if (commitsRaw.length > 0 && Array.isArray(commitsRaw[0].json)) {
  commitsList = commitsRaw[0].json;
} else if (commitsRaw.length > 0 && commitsRaw[0].json && Array.isArray(commitsRaw[0].json.data)) {
  commitsList = commitsRaw[0].json.data;
} else {
  commitsList = commitsRaw.map(i => i.json).filter(j => j && j.sha);
}

const cleanCommits = commitsList.slice(0, 40).map(c => ({
  sha: (c.sha || '').substring(0, 7),
  author: c.commit?.author?.name || c.author?.login || 'Unknown',
  message: (c.commit?.message || '').split('\n')[0],
  date: c.commit?.author?.date || ''
}));

// 2. Process Pull Requests (only merged in the 7-day window)
let prsRaw = $('Fetch Merged Pull Requests').all();
let prsList = [];
if (prsRaw.length > 0 && Array.isArray(prsRaw[0].json)) {
  prsList = prsRaw[0].json;
} else {
  prsList = prsRaw.map(i => i.json).filter(j => j && j.number);
}

const mergedPRs = prsList.filter(pr => {
  if (!pr.merged_at) return false;
  const mergedDate = new Date(pr.merged_at);
  return mergedDate >= sevenDaysAgo;
}).map(pr => ({
  number: pr.number,
  title: pr.title,
  author: pr.user?.login || 'Unknown',
  merged_at: pr.merged_at,
  url: pr.html_url
}));

// 3. Process Closed Issues (excluding PR objects)
let issuesRaw = $('Fetch Closed Issues').all();
let issuesList = [];
if (issuesRaw.length > 0 && Array.isArray(issuesRaw[0].json)) {
  issuesList = issuesRaw[0].json;
} else {
  issuesList = issuesRaw.map(i => i.json).filter(j => j && j.number);
}

const closedIssues = issuesList.filter(issue => {
  if (issue.pull_request) return false; // Filter out PRs returned by issues endpoint
  return true;
}).map(issue => ({
  number: issue.number,
  title: issue.title,
  author: issue.user?.login || 'Unknown',
  closed_at: issue.closed_at,
  url: issue.html_url
}));

// 4. Identify Contributors
const contributors = new Set([
  ...cleanCommits.map(c => c.author),
  ...mergedPRs.map(p => p.author),
  ...closedIssues.map(i => i.author)
]);

const language = (config.language || 'EN').toUpperCase();
const isFrench = language === 'FR';

const systemPrompt = isFrench
  ? `Tu es un Lead Tech et Developer Advocate expert. Tu rédiges un résumé narratif hebdomadaire élégant, précis et engageant de l'activité d'un dépôt GitHub pour l'équipe d'ingénierie et les parties prenantes. Sois concis, clair et percutant.`
  : `You are an expert Tech Lead and Developer Advocate. You write an elegant, precise, and engaging weekly narrative summary of GitHub repository activity for the engineering team and executive stakeholders. Be concise, clear, and impactful.`;

const userPrompt = isFrench
  ? `Génère le résumé hebdomadaire de développement pour le dépôt **${config.github_repo}** couvrant la période du **${config.period_display}**.

Données de la semaine :
- **Commits récents** (${cleanCommits.length}) :
${JSON.stringify(cleanCommits.slice(0, 25), null, 2)}

- **Pull Requests Mergées** (${mergedPRs.length}) :
${JSON.stringify(mergedPRs, null, 2)}

- **Issues Résolues & Clôturées** (${closedIssues.length}) :
${JSON.stringify(closedIssues, null, 2)}

- **Contributeurs Actifs** : ${Array.from(contributors).join(', ') || 'Équipe principale'}

Structure attendue :
1. 🚀 **Faits Marquants & Vue d'Ensemble** (1 paragraphe narratif résumant les avancées majeures)
2. 🔀 **Fonctionnalités & PRs Clés Mergées** (liste des PRs avec contexte d'impact)
3. 🐛 **Bugs Résolus & Améliorations de Stabilité** (problèmes corrigés)
4. 👥 **Contributeurs de la Semaine** (remerciements aux auteurs)
5. 🔮 **Perspectives & Priorités pour la Semaine Suivante** (orientations à venir)

Utilise un style Markdown soigné avec des puces claires et des liens vers les PRs/Issues lorsque disponibles.`
  : `Generate the weekly development summary for repository **${config.github_repo}** covering **${config.period_display}**.

Weekly telemetry:
- **Recent Commits** (${cleanCommits.length}):
${JSON.stringify(cleanCommits.slice(0, 25), null, 2)}

- **Merged Pull Requests** (${mergedPRs.length}):
${JSON.stringify(mergedPRs, null, 2)}

- **Closed Issues** (${closedIssues.length}):
${JSON.stringify(closedIssues, null, 2)}

- **Active Contributors**: ${Array.from(contributors).join(', ') || 'Core team'}

Required Structure:
1. 🚀 **Executive Highlights & Narrative Overview** (1 cohesive paragraph summarizing velocity and shipped milestones)
2. 🔀 **Merged Features & Key Pull Requests** (bulleted list highlighting user/dev impact with PR references)
3. 🐛 **Resolved Issues & Quality Hardening** (closed bugs and operational fixes)
4. 👥 **Weekly Contributors Spotlight** (shoutout to active contributors)
5. 🔮 **Forward Outlook & Next Sprint Priorities** (strategic momentum for the upcoming week)

Format in clean, GitHub-flavored Markdown with bullet points and bold emphasis.`;

const claudeRequestBody = {
  model: config.claude_model || "claude-sonnet-4-20250514",
  max_tokens: 4096,
  system: systemPrompt,
  messages: [
    {
      role: "user",
      content: userPrompt
    }
  ]
};

return [{
  json: {
    ...config,
    stats: {
      commits_count: cleanCommits.length,
      merged_prs_count: mergedPRs.length,
      closed_issues_count: closedIssues.length,
      contributors_count: contributors.size
    },
    claude_request_body: claudeRequestBody,
    anthropic_api_key: config.anthropic_api_key
  }
}];

// Parse Claude response and format for Discord, Slack, and Email
const prev = $('Aggregate Activity & Build Prompt').first().json;
const claudeResponse = $input.first().json;

let summaryMarkdown = '';
if (claudeResponse && claudeResponse.content && Array.isArray(claudeResponse.content)) {
  summaryMarkdown = claudeResponse.content.map(c => c.text || '').join('\n\n');
} else if (claudeResponse && claudeResponse.error) {
  summaryMarkdown = `⚠️ Claude API Notice: ${claudeResponse.error.message || JSON.stringify(claudeResponse.error)}`;
} else {
  summaryMarkdown = typeof claudeResponse === 'string' ? claudeResponse : JSON.stringify(claudeResponse);
}

const headerTitle = `📢 Weekly Dev Summary: ${prev.github_repo} (${prev.period_display})`;

// 1. Slack Payload
const slackPayload = {
  text: `${headerTitle}\n\n${summaryMarkdown}`,
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: `Weekly Dev Summary: ${prev.github_repo}`,
        emoji: True
      }
    },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `📅 *Period:* ${prev.period_display} | 🚀 *Merged PRs:* ${prev.stats?.merged_prs_count || 0} | 🐛 *Closed Issues:* ${prev.stats?.closed_issues_count || 0} | 💻 *Commits:* ${prev.stats?.commits_count || 0}`
        }
      ]
    },
    {
      type: "divider"
    },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: summaryMarkdown.length > 2900 ? summaryMarkdown.substring(0, 2900) + '... (truncated)' : summaryMarkdown
      }
    }
  ]
};

// 2. Discord Payload
const discordPayload = {
  content: `**${headerTitle}**`,
  embeds: [
    {
      title: `📊 Velocity Telemetry (${prev.github_repo})`,
      description: summaryMarkdown.length > 4000 ? summaryMarkdown.substring(0, 3950) + '...' : summaryMarkdown,
      color: 5793266, // Claude purple / blurple
      fields: [
        { name: "Period", value: prev.period_display, inline: True },
        { name: "Merged PRs", value: String(prev.stats?.merged_prs_count || 0), inline: True },
        { name: "Closed Issues", value: String(prev.stats?.closed_issues_count || 0), inline: True }
      ],
      footer: {
        text: "Generated automatically by n8n + Claude Sonnet 4"
      },
      timestamp: new Date().toISOString()
    }
  ]
};

// 3. HTML Email Payload
const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; line-height: 1.6; color: #1f2937; max-width: 720px; margin: 0 auto; padding: 24px; }
    .header { background: linear-gradient(135deg, #4f46e5, #7c3aed); color: #ffffff; padding: 24px; border-radius: 8px; margin-bottom: 24px; }
    .header h1 { margin: 0 0 8px 0; font-size: 24px; }
    .stats-bar { display: flex; gap: 16px; margin: 16px 0; padding: 12px; background: #f3f4f6; border-radius: 6px; font-size: 14px; }
    .content { background: #ffffff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 24px; white-space: pre-wrap; font-family: inherit; }
    .footer { margin-top: 24px; font-size: 12px; color: #6b7280; text-align: center; }
  </style>
</head>
<body>
  <div class="header">
    <h1>Weekly Dev Summary: ${prev.github_repo}</h1>
    <p style="margin: 0; opacity: 0.9;">Period: ${prev.period_display}</p>
  </div>
  <div class="stats-bar">
    <span>🔀 <strong>${prev.stats?.merged_prs_count || 0}</strong> Merged PRs</span>
    <span>🐛 <strong>${prev.stats?.closed_issues_count || 0}</strong> Closed Issues</span>
    <span>💻 <strong>${prev.stats?.commits_count || 0}</strong> Commits</span>
    <span>👥 <strong>${prev.stats?.contributors_count || 0}</strong> Contributors</span>
  </div>
  <div class="content">
${summaryMarkdown}
  </div>
  <div class="footer">
    Sent via automated n8n workflow powered by Claude API (claude-sonnet-4-20250514)
  </div>
</body>
</html>
`;

return [{
  json: {
    ...prev,
    summary_markdown: summaryMarkdown,
    summary_subject: headerTitle,
    slack_payload: slackPayload,
    discord_payload: discordPayload,
    email_html: emailHtml
  }
}];
